package com.fintrack.mapper;

import com.fintrack.dto.user.UserResponse;
import com.fintrack.entity.User;
import org.springframework.stereotype.Component;

/**
 * Converts {@link User} entities into their API projection.
 *
 * <p>Hand-written rather than generated by MapStruct or driven by reflection: the
 * mapping is four lines, and an explicit field list is exactly the property worth
 * having here. A new column on the entity cannot silently appear in an API response
 * -- someone has to add it to this method first.
 */
@Component
public class UserMapper {

    public UserResponse toResponse(User user) {
        return new UserResponse(
                user.getId(),
                user.getName(),
                user.getEmail(),
                user.getRole(),
                user.getStatus(),
                user.getCreatedAt(),
                user.getUpdatedAt()
        );
    }
}
